import { test, expect } from '@playwright/test';

const BASE_URL = process.env.TARGET_URL || 'https://www.saucedemo.com';
const USERNAME = process.env.TARGET_USERNAME || 'standard_user';
const PASSWORD = process.env.TARGET_PASSWORD || 'secret_sauce';

test('Navigate and submit valid credentials', async ({ page }) => {
  // Navigate to the configured target site base URL
  console.log("[Timeline] Navigate: to base URL");
  await page.goto(BASE_URL);

  // Enter the valid username into the username field
  console.log("[Timeline] Enter: username into username field");
  await page.getByLabel('Username').fill(USERNAME);

  // Enter the valid password into the password field
  console.log("[Timeline] Enter: password into password field");
  await page.getByLabel('Password').fill(PASSWORD);

  // Submit the login form
  console.log("[Timeline] Click: login button");
  await page.getByRole('button', { name: 'Login' }).click();

  // Wait for the post-login landing to complete (redirect to authenticated page)
  console.log("[Timeline] Wait: for navigation to authenticated home or dashboard page");
  await expect(page).not.toHaveURL(BASE_URL, { timeout: 15000 });

  // Assert the application accepted valid credentials and redirected away from the login page
  console.log("[Timeline] Assert: user is on authenticated home or dashboard page");
  await expect(page).not.toHaveURL(BASE_URL);
});

